from flask import Flask, Blueprint

# Create the users blueprint
users_bp = Blueprint('users', __name__)

@users_bp.route('/', methods=['GET'])
def list_users():
    return {'users': ['Alice', 'Bob', 'Charlie']}, 200

@users_bp.route('/<int:user_id>', methods=['GET'])
def get_user(user_id):
    return {'id': user_id, 'name': f'User {user_id}'}, 200

@users_bp.route('/', methods=['POST'])
def create_user():
    return {'message': 'User created'}, 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    return {'message': f'User {user_id} updated'}, 200

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    return {'message': f'User {user_id} deleted'}, 204

# Create the main Flask application
app = Flask(__name__)

# Register the users blueprint under /users prefix
app.register_blueprint(users_bp, url_prefix='/users')

@app.route('/', methods=['GET'])
def home():
    return {'message': 'Welcome to the Flask API'}, 200

if __name__ == '__main__':
